/**
 * Unified Cal.com Webhook Parser
 * Handles BOOKING_CREATED, BOOKING_CANCELLED, BOOKING_RESCHEDULED
 * FIX: Uses iCalUID for consistent appointment tracking across reschedules/cancels
 */

const results = [];

for (const item of $input.all()) {
  try {
    const webhook = item.json;

    // Determine event type
    const eventType = webhook.triggerEvent;
    console.log(eventType)


    // Extract attendee info (patient)
    const attendee = webhook.attendees && webhook.attendees[0] ? webhook.attendees[0] : {};
    const patientEmail = attendee.email || "";
    const patientName = attendee.name || "";
    const patientPhone = attendee.phoneNumber || "";

    // Extract appointment details
    const startTime = new Date(webhook.startTime);

    // Human-readable formats
    const humanDate = startTime.toLocaleDateString('en-US', {
      weekday: 'long',
      month: 'long',
      day: 'numeric',
    });
    const humanTime = startTime.toLocaleTimeString('en-US', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: true
    });

    // ISO format for scheduling
    const isoTimeFormat = webhook.startTime;

    // Extract doctor name from title/organizer
    const doctorMatch = webhook.eventTitle?.match(/Dr\.?\s*\w+/i);
    const doctorName = doctorMatch ? doctorMatch[0].trim() : (webhook.organizer?.name || "Dr. Jennifer");

    // Appointment type
    const appointmentType = webhook.userFieldsResponses?.appointmentType?.value || 
                           webhook.responses?.appointmentType?.value || 
                           webhook.description || 
                           "Consultation";

    // For reschedule: Get new time if available
    let newDate = null;
    let newTime = null;
    let newIsoTime = null;

    if (eventType === "BOOKING_RESCHEDULED" && webhook.rescheduleEndTime) {
      const newStartTime = new Date(webhook.rescheduleEndTime);
      newDate = newStartTime.toLocaleDateString('en-US', {
        weekday: 'long',
        month: 'long',
        day: 'numeric',
      });
      newTime = newStartTime.toLocaleTimeString('en-US', {
        hour: '2-digit',
        minute: '2-digit',
        hour12: true
      });
      newIsoTime = webhook.rescheduleEndTime;
    }

    console.log(`📅 ${eventType}: ${patientName} - ${humanDate} at ${humanTime}`);

    results.push({
      json: {
        // Event metadata
        eventType: eventType,
        bookingUid: webhook.uid,
        appointmentUid: webhook.iCalUID || webhook.uid,

        // Patient info
        patientEmail: patientEmail,
        patientName: patientName,
        patientPhone: patientPhone,

        // Appointment details (original/current)
        appointmentDate: humanDate,
        appointmentTime: humanTime,
        isoTimeFormat: isoTimeFormat,
        doctorName: doctorName,
        appointmentType: appointmentType,

        // For reschedule: new appointment details
        newDate: newDate,
        newTime: newTime,
        newIsoTime: newIsoTime,

        // Full webhook for reference
        rawWebhook: webhook
      }
    });

  } catch (error) {
    console.error(`❌ Error parsing Cal.com webhook:`, error.message);
    results.push({
      json: {
        error: error.message,
        rawData: item.json
      }
    });
  }
}

return results;
